from taf.ul.auto_commissioning.generator.custom_mos_mapping import ManagedObject
from taf.ul.auto_commissioning.generator.mos_from_xml import ManagedObjectDictsFromSCF
from taf.ul.auto_commissioning.pydelta import PyDelta


class PyDeltaGenerator:

    def __init__(self, base_scf, full_scf):
        self.get_managed_object_dicts = ManagedObjectDictsFromSCF().get

        self.base_scf_mapping = self._map_objects_by_distname_without_mrbts_nrbts(base_scf)
        self.full_scf_mapping = self._map_objects_by_distname_without_mrbts_nrbts(full_scf)

        self.base_scf_distnames = set(self.base_scf_mapping.keys())
        self.full_scf_distnames = set(self.full_scf_mapping.keys())

    def generate_into_pkl(self, pkl_addr):
        self._create_pydelta_scf().save_to_pickle(pkl_addr)

    def generate_into_json(self, json_addr):
        self._create_pydelta_scf().save_to_json(json_addr)

    def _create_pydelta_scf(self):
        return PyDelta(
            removed=self._get_managed_objects_removed_in_full_scf(),
            added=self._get_managed_objects_added_in_full_scf(),
            changed=self._get_managed_objects_that_differ_from_base_scf()
        )

    def _get_managed_objects_that_differ_from_base_scf(self):
        common_distnames = self.full_scf_distnames.intersection(self.base_scf_distnames)
        diff = []
        for dist in common_distnames:
            if self.base_scf_mapping[dist] != self.full_scf_mapping[dist]:
                diff.append(self.full_scf_mapping[dist])
        return diff

    def _get_managed_objects_removed_in_full_scf(self):
        """Managed objects that are in base, but not present in full scf"""
        distnames_removed_in_full = self.base_scf_distnames.difference(self.full_scf_distnames)
        return [self.base_scf_mapping[dist] for dist in distnames_removed_in_full]

    def _get_managed_objects_added_in_full_scf(self):
        """Managed objects that are in full scf, but not present in base scf"""
        distnames_added_in_full = self.full_scf_distnames.difference(self.base_scf_distnames)
        return [self.full_scf_mapping[dist] for dist in distnames_added_in_full]

    def _map_objects_by_distname_without_mrbts_nrbts(self, scf):
        mos = {}
        for obj in self._get_pythonified_managed_objects(scf):
            if obj.dist_name_without_mr_nr_bts != "":
                mos[obj.dist_name_without_mr_nr_bts] = obj
            else:
                if "NRBTS" in obj.dist_name:
                    mos["NRBTS"] = obj
                elif "MRBTS" in obj.dist_name:
                    mos["MRBTS"] = obj
                else:
                    raise Exception("Invalid distname {}".format(obj.dist_name))
        return mos

    def _get_pythonified_managed_objects(self, scf_addr):
        return [ManagedObject.create_from_xml_dict(i) for i in self.get_managed_object_dicts(scf_addr)]
